int checkSecretCode(int nAlice, int nGuest)
{
    int aliceH = nAlice / 100;
    int aliceT = (nAlice / 10) % 10;
    int aliceO = nAlice % 10;

    int sec3 = nGuest % 1000;
    int sec2 = (nGuest / 1000) % 1000;
    int sec1 = nGuest / 1000000;

    int sum1 = sec1 / 100 + (sec1 / 10) % 10 + sec1 % 10;
    int sum2 = sec2 / 100 + (sec2 / 10) % 10 + sec2 % 10;
    int sum3 = sec3 / 100 + (sec3 / 10) % 10 + sec3 % 10;

    int checked = 0;
    if (sum1 == aliceH) {
        checked = checked + 1;
    }
    if (sum2 == aliceT) {
        checked = checked + 1;
    }
    if (sum3 == aliceO) {
        checked = checked + 1;
    }

    if (checked > 1) {
        return 1;
    }
    return 0;
}
